// The catalogue domain's capabilities.
struct CatalogueApi {
    Client &c;

    // catalogue_indicators's arguments: the required in the constructor, each optional a chained setter.
    struct IndicatorsArgs {
        Json::Object values;

        IndicatorsArgs() {}

        // builtin, script or defined; omitted, every one.
        IndicatorsArgs &source(std::string value) {
            values["source"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

    // Every indicator a study can be attached as: the built-ins, each with its title, family, calculations and default settings, and every custom study a script or a program declared, with its spec, where it came from and who defined it. kind is what study_attach takes.
    // Scope: read. Since: 1.2.0.
    // URI: bentrix://catalogue/indicators{?source}
    Json indicators(const IndicatorsArgs &args) { return c.read_resource("bentrix://catalogue/indicators{?source}", args.json()); }

    // Every built-in and construct of Assay with its disposition (runs, diverges, refused, later) and what it computes, where Bentrix's arithmetic takes a convention, what Bentrix lacks, or the phase it waits for — the table Settings › Assay draws — and every setting Assay scripts run under, with its value now, its default and its choices.
    // Scope: read. Since: 1.5.0.
    // URI: bentrix://catalogue/script-builtins
    Json script_builtins() { return c.read_resource("bentrix://catalogue/script-builtins", Json(Json::Object{})); }

    // Every data source Bentrix knows, by its token (dukascopy, binance, iex): whether this edition carries its door (downloads, its Sources card, lab_create), and its laboratory on this computer when there is one — a laboratory of a source this edition does not carry is shown and replayed, and no more of it can be downloaded. With the edition's name and its release channel. MetaTrader is not a data source here and is in every edition.
    // Scope: read. Since: 1.7.0.
    // URI: bentrix://sources
    Json sources() { return c.read_resource("bentrix://sources", Json(Json::Object{})); }
};

