    struct ScriptCheckArgs {
        Json::Object values;

        explicit ScriptCheckArgs(std::string source) {
            values["source"] = Json(std::move(source));
        }

        // The file's stem the study's id is made from; omitted, the id is script_<8 hex> of the text.
        ScriptCheckArgs &name(std::string value) {
            values["name"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

