    struct ScriptConvertArgs {
        Json::Object values;

        ScriptConvertArgs(std::string source, int64_t to) {
            values["source"] = Json(std::move(source));
            values["to"] = Json(std::move(to));
        }

        Json json() const { return Json(values); }
    };

    // Answers an older script (version 1 to 4, or no version line) written in version 5 or 6 - the text and the edits that make it, one a changed run of lines - as the IDE's Convert command shows it in a diff: the version pass's own reading written onto the source, every comment and the layout kept, computing what the original computes. Refused by name where an edit in place cannot say it (a script declaring its own ta, a strategy's when inside an expression) and for a conversion down. Writes nothing; the agent applies the edits or not.
    // Scope: read. Since: 1.15.0.
