    // script_definition's arguments: the required in the constructor, each optional a chained setter.
    struct ScriptDefinitionArgs {
        Json::Object values;

        ScriptDefinitionArgs(std::string source, int64_t line, int64_t col) {
            values["source"] = Json(std::move(source));
            values["line"] = Json(std::move(line));
            values["col"] = Json(std::move(col));
        }

        Json json() const { return Json(values); }
    };

    // Answers the span where the script declares the name at line and col; null for a built-in or no name. Writes nothing.
