    Json say(const SayArgs &args) { return c.call("room_say", args.json()); }

    // Shares the workbench in front with the room in front, as its creator's Share does: its clock, its charts and their setups are published, never a bar, an order or money; each member's own Bentrix makes the same workbench over its own data.
