    // Answers this session's verification battery: how many of its workbenches settled, and once all did, each of the sixteen checks — its verdict (pass, fail, measured, not run), what it found in a sentence, and its figures.
    // Scope: read. Since: 1.14.0.
    Json battery_get() { return c.call("battery_get", Json(Json::Object{})); }

    // battery_run's arguments: the required in the constructor, each optional a chained setter.
    struct BatteryRunArgs {
        Json::Object values;

        explicit BatteryRunArgs(std::string bench) {
            values["bench"] = Json(std::move(bench));
        }

        Json json() const { return Json(values); }
    };

    // Runs the sixteen checks of Bentrix's own engine on a laboratory workbench's recording: a reference strategy (EMA 8 crossing EMA 21, hourly) at machine speed on workbenches made alike it — as it is, again, on twice the spread, on one-minute OHLC ticks, over the first half of its days — and scripted orders on three more (a buy and a sell held to the middle of the days, a stop and a limit). Answers as battery_get does; battery_get again until every check is answered: pass, fail, measured or not run, each with its reason and figures.
    // Scope: lab. Since: 1.14.0.
    Json battery_run(const BatteryRunArgs &args) { return c.call("battery_run", args.json()); }

    // bench_set_automation's arguments: the required in the constructor, each optional a chained setter.
