    // env_make's arguments: the required in the constructor, each optional a chained setter.
    struct EnvMakeArgs {
        Json::Object values;

        explicit EnvMakeArgs(std::string bench) {
            values["bench"] = Json(std::move(bench));
        }

        // discrete (0 flat, 1 long, 2 short; the default), continuous (a target in [-1, 1]) or order (side, size, stop and target in points).
        EnvMakeArgs &action(std::string value) {
            values["action"] = Json(std::move(value));
            return *this;
        }

        // A continuous action's flat zone, by default 0.1.
        EnvMakeArgs &deadband(double value) {
            values["deadband"] = Json(std::move(value));
            return *this;
        }

        // tape (the whole days), window (episode_bars candles from the seed's draw; the default) or session (one day).
        EnvMakeArgs &episode(std::string value) {
            values["episode"] = Json(std::move(value));
            return *this;
        }

        // A window episode's candles, by default 200.
        EnvMakeArgs &episode_bars(int64_t value) {
            values["episode_bars"] = Json(std::move(value));
            return *this;
        }

        // Follow a clock someone else moves rather than drive it — a paper or REAL workbench always does; a laboratory one may (a replay the person plays, acted on at each close): no rewind, env_act and env_observe.
        EnvMakeArgs &follow(bool value) {
            values["follow"] = Json(std::move(value));
            return *this;
        }

        // A curriculum: window episodes lengthening from first to last candles over `over` episodes.
        EnvMakeArgs &growing(Json value) {
            values["growing"] = Json(std::move(value));
            return *this;
        }

        // With participation: the reward charged impact x units / the candle's volume - never the account.
        EnvMakeArgs &impact(double value) {
            values["impact"] = Json(std::move(value));
            return *this;
        }

        // The interval a step lasts (M1 to W1), by default H1.
        EnvMakeArgs &interval(std::string value) {
            values["interval"] = Json(std::move(value));
            return *this;
        }

        // The lots a whole position holds, by default 0.01.
        EnvMakeArgs &lots(double value) {
            values["lots"] = Json(std::move(value));
            return *this;
        }

        // An order action's largest stop or target, in points, by default 10000.
        EnvMakeArgs &max_points(double value) {
            values["max_points"] = Json(std::move(value));
            return *this;
        }

        // On a live workbench: the steps after which an episode is truncated.
        EnvMakeArgs &max_steps(int64_t value) {
            values["max_steps"] = Json(std::move(value));
            return *this;
        }

        // A modelled participation cap: an order's units at most this share of the last closed candle's volume, in (0, 1].
        EnvMakeArgs &participation(double value) {
            values["participation"] = Json(std::move(value));
            return *this;
        }

        // The reward plugin, by default dsr_dd_penalty@1.
        EnvMakeArgs &reward(std::string value) {
            values["reward"] = Json(std::move(value));
            return *this;
        }

        // The share of the opening equity at or below which an episode ends in ruin, by default 0.5.
        EnvMakeArgs &ruin(double value) {
            values["ruin"] = Json(std::move(value));
            return *this;
        }

        // The market, by default the workbench's first.
        EnvMakeArgs &symbol(std::string value) {
            values["symbol"] = Json(std::move(value));
            return *this;
        }

        // The closed candles an observation holds, by default 32.
        EnvMakeArgs &window(int64_t value) {
            values["window"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

    // Makes a reinforcement-learning environment over a workbench - observations of the closed candles and the account, discrete, continuous or order actions, eight named rewards, tape, window or session episodes (a growing curriculum optional), a modelled participation cap - and answers its id with its observation and action spaces. On a laboratory workbench env_reset starts an episode, env_step takes an action, run_episode runs a list; the workbench is rewound at each reset, its deals undone, so give it one of its own. On a paper or REAL workbench the clock is the market's: env_reset at a close, env_act, then env_observe at the next close. env_close lets it go.
    // Scope: lab. Since: 1.14.0.
    Json env_make(const EnvMakeArgs &args) { return c.call("env_make", args.json()); }

    // env_observe's arguments: the required in the constructor, each optional a chained setter.
    struct EnvObserveArgs {
        Json::Object values;

        EnvObserveArgs(std::string env, int64_t at_ms) {
            values["env"] = Json(std::move(env));
            values["at_ms"] = Json(std::move(at_ms));
        }

        // False when no candle closed since the last observation (the market said nothing): the episode is truncated.
        EnvObserveArgs &moved(bool value) {
            values["moved"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

    // Answers where an environment's episode stands at the close at_ms: the observation, the reward of the move since the last env_act, terminated (ruin), truncated (no candle closed, or the episode's steps) and info. On a live workbench it follows env_act at each close; on a laboratory workbench standing at at_ms it reads the observation a laboratory step would.
