    // URI: bentrix://screen{?group,page}
    Json screen(const ScreenArgs &args) { return c.read_resource("bentrix://screen{?group,page}", args.json()); }

    // Every page of screen, following next until it is absent.
    std::vector<Json> screen_pages(const ScreenArgs &args) { return c.read_pages("bentrix://screen{?group,page}", args.json()); }

    // The application as the person sees it, as get_state answers at depth charts: the shown area, the selected workbench, every laboratory and real account with its workbenches and their chart windows. Every node carries its uri.
    // Scope: read. Since: 1.0.0.
    // URI: bentrix://workspace
    Json state() { return c.read_resource("bentrix://workspace", Json(Json::Object{})); }
