// The zone domain's capabilities.
struct ZoneApi {
    Client &c;

    // bars_in_zone's arguments: the required in the constructor, each optional a chained setter.
    struct BarsInZoneArgs {
        Json::Object values;

        BarsInZoneArgs(std::string bench, std::string symbol, std::string timeframe, std::string zone) {
            values["bench"] = Json(std::move(bench));
            values["symbol"] = Json(std::move(symbol));
            values["timeframe"] = Json(std::move(timeframe));
            values["zone"] = Json(std::move(zone));
        }

        // The newest bars kept, 200 when omitted, at most 2000.
        BarsInZoneArgs &limit(int64_t value) {
            values["limit"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

    // Answers a workbench's candles of one market and interval read and cut in a time zone of the caller's choosing, without changing what the screen shows: a day opens at that zone's midnight, a week at its Monday, H4 on its grid — folded from the workbench's own finer candles (H1, or M30/M15 for a half- or quarter-hour zone), up to the cursor and never past it. Rows are time_ms (the workbench's own stamps), zone_time (the bar's open in that zone), open, high, low, close, tick_volume; newest limit (200 when omitted, at most 2000), oldest first. An interval the zone does not move is read as it is.
    // Scope: read. Since: 3.12.0.
    Json bars_in_zone(const BarsInZoneArgs &args) { return c.call("bars_in_zone", args.json()); }

    // bench_set_display_zone's arguments: the required in the constructor, each optional a chained setter.
    struct BenchSetDisplayZoneArgs {
        Json::Object values;

        BenchSetDisplayZoneArgs(std::string bench, std::string zone) {
            values["bench"] = Json(std::move(bench));
            values["zone"] = Json(std::move(zone));
        }

        Json json() const { return Json(values); }
    };

    // Sets the time zone a workbench's charts are read in and their candles cut in, as a press on the clock's charts' face does: every chart of the workbench follows; its venue, strategies and swap keep the workbench's own clock. default puts the workbench's own zone (or its broker's) back. Answers the zone.
    // Scope: lab. Since: 3.12.0.
    Json bench_set_display_zone(const BenchSetDisplayZoneArgs &args) { return c.call("bench_set_display_zone", args.json()); }

    // chart_set_zone's arguments: the required in the constructor, each optional a chained setter.
    struct ChartSetZoneArgs {
        Json::Object values;

        ChartSetZoneArgs(std::string chart, std::string zone) {
            values["chart"] = Json(std::move(chart));
            values["zone"] = Json(std::move(zone));
        }

        Json json() const { return Json(values); }
    };

    // Sets one chart's own time zone, as its settings' Time zone row does: its times read and its candles cut in it, a preview of that chart alone — the workbench's other charts and the clock as they were. default reads it as its workbench again. Answers the chart's zone.
    // Scope: lab. Since: 3.12.0.
    Json chart_set_zone(const ChartSetZoneArgs &args) { return c.call("chart_set_zone", args.json()); }

    // Answers the clock window as it reads the selected workbench: each clock it shows (market: the broker's or the laboratory's zone; computer: this computer's; charts: the workbench's display zone) with its time, region and offset; the workbench's display zone, chosen or default; and the clock's own settings (which clocks, face, hours, parts, sections, desks, band, glow window, close-together line).
    // Scope: read. Since: 3.12.0.
    Json clock_read() { return c.call("clock_read", Json(Json::Object{})); }

    // clock_settings_set's arguments: the required in the constructor, each optional a chained setter.
    struct ClockSettingsSetArgs {
        Json::Object values;

        explicit ClockSettingsSetArgs(Json settings) {
            values["settings"] = Json(std::move(settings));
        }

        Json json() const { return Json(values); }
    };

    // Changes the clock window's own settings, as its gear's window does — the fields given laid over the rest. Answers the settings.
    // Scope: lab. Since: 3.12.0.
    Json clock_settings_set(const ClockSettingsSetArgs &args) { return c.call("clock_settings_set", args.json()); }

    // zones_list's arguments: the required in the constructor, each optional a chained setter.
    struct ZonesListArgs {
        Json::Object values;

        ZonesListArgs() {}

        // Only the zones whose code or name holds this text (case does not matter).
        ZonesListArgs &search(std::string value) {
            values["search"] = Json(std::move(value));
            return *this;
        }

        Json json() const { return Json(values); }
    };

    // Answers every time zone Bentrix offers, in the order its lists show them: system (this computer's), the important ones (UTC, New York close, New York, London, Tokyo, Chicago, Frankfurt, Eastern Europe, Dubai, Singapore, Hong Kong, Sydney), every zone of the IANA database and the fixed offsets — each its code (what the other zone tools take), label, region, offsets across the year and offset now. search narrows them.
    // Scope: read. Since: 3.12.0.
    Json zones_list(const ZonesListArgs &args) { return c.call("zones_list", args.json()); }
};

// One Bentrix endpoint, every capability of its catalogue under b.<domain>. Neither copied nor moved: each
// domain holds a reference to it.
class Bentrix : public Client {
  public:
    AccountApi account{*this};
    AccountsApi accounts{*this};
    AgentApi agent{*this};
    AlertApi alert{*this};
    AlertsApi alerts{*this};
    BenchApi bench{*this};
    CatalogueApi catalogue{*this};
    ChartApi chart{*this};
    DataApi data{*this};
    DrawingApi drawing{*this};
    DriversApi drivers{*this};
    ForecastApi forecast{*this};
    IndicatorApi indicator{*this};
    LaboratoryApi laboratory{*this};
    MarketwatchApi marketwatch{*this};
    ModelApi model{*this};
    OutputApi output{*this};
    RecordingsApi recordings{*this};
    ReplayApi replay{*this};
    RoomApi room{*this};
    SettingsApi settings{*this};
    StrategyApi strategy{*this};
    StudyApi study{*this};
    TemplateApi template_{*this};
    TradeApi trade{*this};
    TradingApi trading{*this};
    WorkbenchApi workbench{*this};
    WorkspaceApi workspace{*this};
    ZoneApi zone{*this};

    Bentrix(std::string url, std::string token) : Client(std::move(url), std::move(token), CATALOGUE_VERSION) {}
    Bentrix(const Bentrix &) = delete;
    Bentrix &operator=(const Bentrix &) = delete;

    // Find the running application through its agents folder, pair under name (empty: the default), connect.
    static Bentrix connect(const std::string &name = "") {
        auto [url, token] = discover("", name);
        return Bentrix(url, token);
    }
};

